class Solution {
  private static String minRotation(String s) {
    int n = s.length();
    if (n == 0) return s;
    String d = s + s;
    int i = 0, j = 1, k = 0;
    while (i < n && j < n && k < n) {
      char a = d.charAt(i + k), b = d.charAt(j + k);
      if (a == b) {
        k++;
        continue;
      }
      if (a > b) i += k + 1;
      else j += k + 1;
      if (i == j) j++;
      k = 0;
    }
    int start = Math.min(i, j);
    return d.substring(start, start + n);
  }

  public int minimumGroups(String[] words) {
    java.util.HashSet<String> groups = new java.util.HashSet<>();
    for (String w : words) {
      StringBuilder even = new StringBuilder(), odd = new StringBuilder();
      for (int i = 0; i < w.length(); i++) {
        if (i % 2 == 0) even.append(w.charAt(i));
        else odd.append(w.charAt(i));
      }
      groups.add(minRotation(even.toString()) + "|" + minRotation(odd.toString()));
    }
    return groups.size();
  }
}
